+      display: inline-flex;
+      align-items: center;
+      gap: 8px;
+      padding: 8px 12px;
+      border-radius: 999px;
+      background: var(--accent-soft);
+      color: var(--accent);
+      font-size: 0.875rem;
+      font-weight: 600;
+      letter-spacing: 0.01em;
+    }
+
+    h1 {
+      margin: 16px 0 10px;
+      font-size: clamp(2.2rem, 4vw, 3.75rem);
+      line-height: 1.02;
+      letter-spacing: -0.04em;
+    }
+
+    .lede {
+      margin: 0;
+      max-width: 58ch;
+      font-size: 1.05rem;
+      line-height: 1.65;
+      color: var(--muted);
+    }
+
+    .faq {
+      display: grid;
+      gap: 16px;
+      margin-top: 32px;
+    }
+
+    .example {
+      overflow: hidden;
+      border: 1px solid var(--card-border);
+      border-radius: 20px;
+      background: var(--card);
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(14px);
+    }
+
+    .question {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 20px;
+      width: 100%;
+      padding: 22px 24px;
+      border: 0;
+      background: transparent;
+      color: var(--text);
+      font: inherit;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question:hover {
+      background: rgba(124, 58, 237, 0.04);
+    }
+
+    .question:focus-visible {
+      outline: 3px solid rgba(124, 58, 237, 0.35);
+      outline-offset: -3px;
+    }
+
+    .question-text {
+      font-size: 1.05rem;
+      font-weight: 700;
+      line-height: 1.4;
+    }
+
+    .icon {
+      flex: 0 0 auto;
+      width: 38px;
+      height: 38px;
+      border-radius: 50%;
+      display: grid;
+      place-items: center;
+      background: var(--accent-soft);
+      color: var(--accent);
+      font-size: 1.2rem;
+      font-weight: 700;
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .details {
+      max-height: 0;
+      overflow: hidden;
+      padding: 0 24px;
+      color: var(--muted);
+      line-height: 1.7;
+      transition: max-height 220ms ease, padding 220ms ease;
+    }
+
+    .example.open .details {
+      padding: 0 24px 22px;
+    }
+
+    .example.open .icon {
+      transform: rotate(45deg);
+      background: rgba(124, 58, 237, 0.18);
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        width: min(100% - 20px, 920px);
+        padding: 32px 0 48px;
+      }
+
+      .question,
+      .details {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+
+      .example.open .details {
+        padding-bottom: 18px;
+      }
+
+      .question-text {
+        font-size: 1rem;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <section class="hero" aria-labelledby="faq-title">
+      <span class="eyebrow">Cat FAQ</span>
+      <h1 id="faq-title">Everything you wanted to know about cats</h1>
+      <p class="lede">A compact, friendly FAQ about cat behavior, care, and what makes them such endlessly fascinating companions.</p>
+    </section>
+
+    <section class="faq" aria-label="Frequently asked questions">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
+          <span class="question-text">Why do cats knead with their paws?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-1" role="region" aria-labelledby="question-1">
+          <p>Cats knead to show comfort and contentment. The motion is a kittenhood behavior that often carries into adulthood as a soothing habit, especially when they feel safe and relaxed.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-2" id="question-2">
+          <span class="question-text">Why do cats purr?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-2" role="region" aria-labelledby="question-2">
+          <p>Most cats purr when they are happy, but they may also purr to self-soothe, communicate, or feel better when they are nervous or unwell. The sound is part comfort signal, part cat mystery.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-3" id="question-3">
+          <span class="question-text">Do cats need baths?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-3" role="region" aria-labelledby="question-3">
+          <p>Usually, no. Cats are very good at grooming themselves. Baths are only needed when a cat gets especially dirty, has something sticky on their coat, or a veterinarian recommends one.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-4" id="question-4">
+          <span class="question-text">Why do cats stare at you?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-4" role="region" aria-labelledby="question-4">
+          <p>Cats stare to gather information. They may be reading your mood, waiting for food, or simply observing the world with intense feline curiosity.</p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll(".example").forEach((item) => {
+      const button = item.querySelector(".question");
+      const panel = item.querySelector(".details");
+
+      const syncState = () => {
+        const expanded = button.getAttribute("aria-expanded") === "true";
+        panel.style.maxHeight = expanded ? `${panel.scrollHeight}px` : "0px";
+        item.classList.toggle("open", expanded);
+      };
+
+      syncState();
+
+      button.addEventListener("click", () => {
+        const expanded = button.getAttribute("aria-expanded") === "true";
+        button.setAttribute("aria-expanded", String(!expanded));
+        syncState();
+      });
+
+      window.addEventListener("resize", syncState);
+    });
+  </script>
+</body>
+</html>
*** End Patch
